    svg.querySelectorAll('.xfi-ch[tabindex]').forEach(g => { g.onkeydown = e => { if (e.key !== 'Enter' && e.key !== ' ') return; e.preventDefault(); foco = '.xfi-ch[tabindex]'; toca(g.dataset); }; });
